CREATE TABLE notes (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, title VARCHAR(500) NOT NULL, body_md CLOB NOT NULL, source VARCHAR(16) NOT NULL, source_url CLOB DEFAULT NULL, status VARCHAR(16) NOT NULL, last_actor VARCHAR(16) DEFAULT 'human' NOT NULL, import_path VARCHAR(600) DEFAULT NULL, summary CLOB DEFAULT NULL, summary_by VARCHAR(120) DEFAULT NULL, enriched_at DATETIME DEFAULT NULL, version INTEGER DEFAULT 1 NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, created_by_token_id INTEGER DEFAULT NULL, last_actor_token_id INTEGER DEFAULT NULL, CONSTRAINT FK_11BA68C41049147 FOREIGN KEY (created_by_token_id) REFERENCES api_tokens (id) NOT DEFERRABLE INITIALLY IMMEDIATE, CONSTRAINT FK_11BA68C829C932B FOREIGN KEY (last_actor_token_id) REFERENCES api_tokens (id) ON DELETE SET NULL NOT DEFERRABLE INITIALLY IMMEDIATE);
CREATE INDEX IDX_11BA68C41049147 ON notes (created_by_token_id);
CREATE INDEX IDX_11BA68C829C932B ON notes (last_actor_token_id);
CREATE INDEX idx_notes_status ON notes (status);
CREATE INDEX idx_notes_updated ON notes (updated_at);
CREATE INDEX idx_notes_last_actor ON notes (last_actor);
CREATE TABLE note_tag (note_id INTEGER NOT NULL, tag_id INTEGER NOT NULL, PRIMARY KEY (note_id, tag_id), CONSTRAINT FK_737A976326ED0855 FOREIGN KEY (note_id) REFERENCES notes (id) ON DELETE CASCADE NOT DEFERRABLE INITIALLY IMMEDIATE, CONSTRAINT FK_737A9763BAD26311 FOREIGN KEY (tag_id) REFERENCES tags (id) ON DELETE CASCADE NOT DEFERRABLE INITIALLY IMMEDIATE);
CREATE INDEX IDX_737A976326ED0855 ON note_tag (note_id);
CREATE INDEX IDX_737A9763BAD26311 ON note_tag (tag_id);
CREATE TABLE curation_presets (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, name VARCHAR(60) NOT NULL, fields CLOB NOT NULL, version INTEGER DEFAULT 1 NOT NULL, is_standard BOOLEAN DEFAULT 0 NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE UNIQUE INDEX uniq_curation_presets_name ON curation_presets (name);
CREATE UNIQUE INDEX uniq_curation_presets_standard ON curation_presets (is_standard) WHERE is_standard;
CREATE TABLE search_presets (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, name VARCHAR(60) NOT NULL, icon VARCHAR(32) NOT NULL, "query" VARCHAR(500) NOT NULL, tag_ids CLOB NOT NULL, status VARCHAR(16) NOT NULL, added_by INTEGER DEFAULT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE UNIQUE INDEX uniq_search_presets_name ON search_presets (name);
CREATE TABLE note_revisions (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, note_id INTEGER NOT NULL, title VARCHAR(500) NOT NULL, body_md CLOB DEFAULT NULL, body_diff CLOB DEFAULT NULL, summary CLOB DEFAULT NULL, tags CLOB NOT NULL, replaced_by VARCHAR(16) NOT NULL, operation VARCHAR(24) DEFAULT NULL, change_title VARCHAR(120) DEFAULT NULL, amended_by_operator BOOLEAN DEFAULT 0 NOT NULL, replaced_at DATETIME NOT NULL, note_updated_at DATETIME NOT NULL, replaced_by_token_id INTEGER DEFAULT NULL, CONSTRAINT FK_9E16C71AB7089A09 FOREIGN KEY (replaced_by_token_id) REFERENCES api_tokens (id) ON DELETE SET NULL NOT DEFERRABLE INITIALLY IMMEDIATE);
CREATE INDEX IDX_9E16C71AB7089A09 ON note_revisions (replaced_by_token_id);
CREATE INDEX idx_note_revisions_note ON note_revisions (note_id, replaced_at);
CREATE INDEX idx_note_revisions_replaced ON note_revisions (replaced_at);
CREATE TABLE api_tokens (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, name VARCHAR(120) NOT NULL, created_at DATETIME NOT NULL, last_used_at DATETIME DEFAULT NULL, revoked_at DATETIME DEFAULT NULL, guide_read_at DATETIME DEFAULT NULL, skills_seen VARCHAR(16) DEFAULT NULL, personalization_seen VARCHAR(16) DEFAULT NULL, role VARCHAR(16) DEFAULT 'agent' NOT NULL, display_name VARCHAR(80) DEFAULT NULL, description CLOB DEFAULT NULL, icon_key VARCHAR(40) DEFAULT NULL, icon_blob BLOB DEFAULT NULL, curation_preset_id INTEGER DEFAULT NULL, CONSTRAINT FK_2CAD560E55F0155A FOREIGN KEY (curation_preset_id) REFERENCES curation_presets (id) ON DELETE SET NULL NOT DEFERRABLE INITIALLY IMMEDIATE);
CREATE INDEX IDX_2CAD560E55F0155A ON api_tokens (curation_preset_id);
CREATE TABLE curator_log (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, token_name VARCHAR(120) NOT NULL, "action" VARCHAR(32) NOT NULL, description CLOB NOT NULL, note_title VARCHAR(500) DEFAULT NULL, retired_note_id INTEGER DEFAULT NULL, operator_comment CLOB DEFAULT NULL , is_precedent BOOLEAN DEFAULT 0 NOT NULL , claims CLOB DEFAULT NULL, affected_note_ids CLOB DEFAULT NULL, run_started_at DATETIME DEFAULT NULL, created_at DATETIME NOT NULL, token_id INTEGER DEFAULT NULL, note_id INTEGER DEFAULT NULL, proposal_id INTEGER DEFAULT NULL, run_id INTEGER DEFAULT NULL, curation_run_id INTEGER DEFAULT NULL, CONSTRAINT FK_F142104441DEE7B9 FOREIGN KEY (token_id) REFERENCES api_tokens (id) ON DELETE SET NULL NOT DEFERRABLE INITIALLY IMMEDIATE, CONSTRAINT FK_F142104426ED0855 FOREIGN KEY (note_id) REFERENCES notes (id) ON DELETE SET NULL NOT DEFERRABLE INITIALLY IMMEDIATE, CONSTRAINT FK_F1421044F4792058 FOREIGN KEY (proposal_id) REFERENCES edit_proposals (id) ON DELETE SET NULL NOT DEFERRABLE INITIALLY IMMEDIATE, CONSTRAINT FK_F142104484E3FEC4 FOREIGN KEY (run_id) REFERENCES curator_log (id) ON DELETE SET NULL NOT DEFERRABLE INITIALLY IMMEDIATE, CONSTRAINT FK_F1421044460D2CF3 FOREIGN KEY (curation_run_id) REFERENCES curator_log (id) ON DELETE SET NULL NOT DEFERRABLE INITIALLY IMMEDIATE);
CREATE INDEX IDX_F142104441DEE7B9 ON curator_log (token_id);
CREATE INDEX IDX_F1421044F4792058 ON curator_log (proposal_id);
CREATE INDEX IDX_F142104484E3FEC4 ON curator_log (run_id);
CREATE INDEX IDX_F1421044460D2CF3 ON curator_log (curation_run_id);
CREATE INDEX idx_curator_log_created ON curator_log (created_at);
CREATE INDEX idx_curator_log_note ON curator_log (note_id);
CREATE INDEX idx_curator_log_precedent ON curator_log (created_at) WHERE is_precedent;
CREATE INDEX idx_curator_log_retired_note ON curator_log (retired_note_id) WHERE retired_note_id IS NOT NULL;
CREATE INDEX idx_curator_log_run ON curator_log (run_id) WHERE run_id IS NOT NULL;
CREATE INDEX idx_curator_log_curation_run ON curator_log (curation_run_id) WHERE curation_run_id IS NOT NULL;
CREATE TABLE retired_tags (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, name VARCHAR(64) NOT NULL, note_count INTEGER NOT NULL, merged_into VARCHAR(64) DEFAULT NULL, retired_at DATETIME NOT NULL);
CREATE UNIQUE INDEX uniq_retired_tag_name ON retired_tags (name);
CREATE TABLE tags (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, name VARCHAR(64) NOT NULL);
CREATE UNIQUE INDEX uniq_tag_name ON tags (name);
CREATE TABLE provider_spend (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, occurred_at DATETIME NOT NULL, surface VARCHAR(16) NOT NULL, operation VARCHAR(32) NOT NULL, provider VARCHAR(32) NOT NULL, model VARCHAR(64) DEFAULT NULL, payer VARCHAR(16) NOT NULL, unit VARCHAR(16) NOT NULL, input_tokens INTEGER DEFAULT NULL, output_tokens INTEGER DEFAULT NULL, succeeded BOOLEAN DEFAULT 1 NOT NULL, credential_id INTEGER DEFAULT NULL, CONSTRAINT FK_B58492492558A7A5 FOREIGN KEY (credential_id) REFERENCES ai_credentials (id) ON DELETE SET NULL NOT DEFERRABLE INITIALLY IMMEDIATE);
CREATE INDEX IDX_B58492492558A7A5 ON provider_spend (credential_id);
CREATE INDEX idx_provider_spend_occurred ON provider_spend (occurred_at);
CREATE TABLE edit_proposals (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, proposed_title VARCHAR(500) DEFAULT NULL, proposed_body_md CLOB DEFAULT NULL, proposed_tags CLOB DEFAULT NULL, proposed_summary CLOB DEFAULT NULL, proposed_patch CLOB DEFAULT NULL, prev_summary CLOB DEFAULT NULL, change_title VARCHAR(120) DEFAULT NULL, comment CLOB DEFAULT NULL, type VARCHAR(16) DEFAULT 'edit' NOT NULL, status VARCHAR(16) DEFAULT 'held' NOT NULL, applied_at DATETIME DEFAULT NULL, prev_title VARCHAR(500) DEFAULT NULL, prev_body_md CLOB DEFAULT NULL, prev_tags CLOB DEFAULT NULL, created_at DATETIME NOT NULL, revised_at DATETIME DEFAULT NULL, revision INTEGER DEFAULT 0 NOT NULL, note_id INTEGER NOT NULL, proposed_by_token_id INTEGER DEFAULT NULL, merge_into_note_id INTEGER DEFAULT NULL, CONSTRAINT FK_E723AC4726ED0855 FOREIGN KEY (note_id) REFERENCES notes (id) ON DELETE CASCADE NOT DEFERRABLE INITIALLY IMMEDIATE, CONSTRAINT FK_E723AC471ACF3C7C FOREIGN KEY (proposed_by_token_id) REFERENCES api_tokens (id) NOT DEFERRABLE INITIALLY IMMEDIATE, CONSTRAINT FK_E723AC47AFEB1A86 FOREIGN KEY (merge_into_note_id) REFERENCES notes (id) ON DELETE CASCADE NOT DEFERRABLE INITIALLY IMMEDIATE);
CREATE INDEX IDX_E723AC471ACF3C7C ON edit_proposals (proposed_by_token_id);
CREATE INDEX IDX_E723AC47AFEB1A86 ON edit_proposals (merge_into_note_id);
CREATE INDEX idx_edit_proposals_note ON edit_proposals (note_id);
CREATE INDEX idx_edit_proposals_status ON edit_proposals (status);
CREATE TABLE skill_serves (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, slug VARCHAR(64) NOT NULL, preset_version INTEGER DEFAULT 0 NOT NULL, path VARCHAR(16) NOT NULL, served_at DATETIME NOT NULL, version VARCHAR(16) DEFAULT NULL, token_id INTEGER DEFAULT NULL, preset_id INTEGER DEFAULT NULL, CONSTRAINT FK_220B17441DEE7B9 FOREIGN KEY (token_id) REFERENCES api_tokens (id) ON DELETE SET NULL NOT DEFERRABLE INITIALLY IMMEDIATE, CONSTRAINT FK_220B17480688E6F FOREIGN KEY (preset_id) REFERENCES curation_presets (id) ON DELETE SET NULL NOT DEFERRABLE INITIALLY IMMEDIATE);
CREATE INDEX IDX_220B17441DEE7B9 ON skill_serves (token_id);
CREATE INDEX IDX_220B17480688E6F ON skill_serves (preset_id);
CREATE INDEX idx_skill_serves_time ON skill_serves (served_at);
CREATE INDEX idx_skill_serves_slug_time ON skill_serves (slug, served_at);
CREATE INDEX skill_serves_token_slug_version ON skill_serves (token_id, slug, version);
CREATE TABLE note_links (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, raw_target VARCHAR(500) NOT NULL, from_note_id INTEGER NOT NULL, to_note_id INTEGER DEFAULT NULL, CONSTRAINT FK_B49202CFA0B3EBFA FOREIGN KEY (from_note_id) REFERENCES notes (id) ON DELETE CASCADE NOT DEFERRABLE INITIALLY IMMEDIATE, CONSTRAINT FK_B49202CFA87535A0 FOREIGN KEY (to_note_id) REFERENCES notes (id) ON DELETE SET NULL NOT DEFERRABLE INITIALLY IMMEDIATE);
CREATE INDEX IDX_B49202CFA0B3EBFA ON note_links (from_note_id);
CREATE INDEX idx_note_links_to ON note_links (to_note_id);
CREATE UNIQUE INDEX uniq_note_link_target ON note_links (from_note_id, raw_target);
CREATE TABLE settings (id INTEGER NOT NULL, ai_enabled BOOLEAN DEFAULT 0 NOT NULL, ai_model VARCHAR(64) DEFAULT NULL, personalization CLOB DEFAULT NULL, appearance CLOB DEFAULT NULL, map_settings CLOB DEFAULT NULL, locale VARCHAR(8) DEFAULT NULL, icon_key VARCHAR(64) DEFAULT NULL, icon_blob BLOB DEFAULT NULL, welcome_completed_at DATETIME DEFAULT NULL, updated_at DATETIME NOT NULL, ai_credential_id INTEGER DEFAULT NULL, embed_credential_id INTEGER DEFAULT NULL, PRIMARY KEY (id), CONSTRAINT FK_E545A0C5146D9B83 FOREIGN KEY (ai_credential_id) REFERENCES ai_credentials (id) ON DELETE SET NULL NOT DEFERRABLE INITIALLY IMMEDIATE, CONSTRAINT FK_E545A0C5EC5EF0C6 FOREIGN KEY (embed_credential_id) REFERENCES ai_credentials (id) ON DELETE SET NULL NOT DEFERRABLE INITIALLY IMMEDIATE);
CREATE INDEX IDX_E545A0C5146D9B83 ON settings (ai_credential_id);
CREATE INDEX IDX_E545A0C5EC5EF0C6 ON settings (embed_credential_id);
CREATE TABLE ai_credentials (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, provider VARCHAR(32) NOT NULL, name VARCHAR(60) NOT NULL, api_key_enc CLOB NOT NULL, api_key_hint VARCHAR(8) NOT NULL, verified_at DATETIME DEFAULT NULL, last_used_at DATETIME DEFAULT NULL, created_at DATETIME NOT NULL);
CREATE TABLE curation_flags (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, comment CLOB NOT NULL, flagged_by_name VARCHAR(120) NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME DEFAULT NULL, resolved_at DATETIME DEFAULT NULL, resolved_by VARCHAR(120) DEFAULT NULL, resolution CLOB DEFAULT NULL, note_id INTEGER NOT NULL, CONSTRAINT FK_3228D10626ED0855 FOREIGN KEY (note_id) REFERENCES notes (id) ON DELETE CASCADE NOT DEFERRABLE INITIALLY IMMEDIATE);
CREATE INDEX IDX_3228D10626ED0855 ON curation_flags (note_id);
CREATE INDEX idx_curation_flags_open ON curation_flags (resolved_at, created_at);
CREATE UNIQUE INDEX uniq_curation_flags_open_note ON curation_flags (note_id) WHERE resolved_at IS NULL;
INSERT INTO settings (id, ai_enabled, updated_at) VALUES (1, 0, CURRENT_TIMESTAMP);
CREATE TRIGGER edit_proposal_revision AFTER UPDATE ON edit_proposals WHEN NEW.revision <= OLD.revision BEGIN UPDATE edit_proposals SET revision = OLD.revision + 1 WHERE id = NEW.id; END;
CREATE TABLE deleted_notes (id INTEGER NOT NULL PRIMARY KEY, created_by_token_id INTEGER DEFAULT NULL, title VARCHAR(500) NOT NULL, body_md CLOB DEFAULT NULL, summary CLOB DEFAULT NULL, tags CLOB NOT NULL, source VARCHAR(16) NOT NULL, source_url CLOB DEFAULT NULL, import_path VARCHAR(1000) DEFAULT NULL, status VARCHAR(16) NOT NULL, last_actor VARCHAR(16) NOT NULL, enriched_at DATETIME DEFAULT NULL, note_created_at DATETIME NOT NULL, note_updated_at DATETIME NOT NULL, deleted_at DATETIME NOT NULL, deleted_by VARCHAR(120) NOT NULL, deleted_reason CLOB DEFAULT NULL, purge_after DATETIME NOT NULL, purged_at DATETIME DEFAULT NULL, summary_by VARCHAR(120) DEFAULT NULL, last_actor_token_id INTEGER DEFAULT NULL);
CREATE INDEX idx_deleted_notes_purge ON deleted_notes (purge_after) WHERE purged_at IS NULL;
CREATE INDEX idx_deleted_notes_deleted ON deleted_notes (deleted_at);
CREATE TABLE skill_settings (note_id INTEGER NOT NULL PRIMARY KEY, slug VARCHAR(64) NOT NULL, enabled BOOLEAN DEFAULT 1 NOT NULL, auto BOOLEAN DEFAULT 1 NOT NULL, command BOOLEAN DEFAULT 1 NOT NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_skill_settings_note FOREIGN KEY (note_id) REFERENCES notes (id) ON DELETE CASCADE);
CREATE UNIQUE INDEX uniq_skill_settings_slug ON skill_settings (slug);
CREATE TABLE skill_grants (note_id INTEGER NOT NULL, token_id INTEGER NOT NULL, PRIMARY KEY (note_id, token_id), CONSTRAINT fk_skill_grants_note FOREIGN KEY (note_id) REFERENCES notes (id) ON DELETE CASCADE, CONSTRAINT fk_skill_grants_token FOREIGN KEY (token_id) REFERENCES api_tokens (id) ON DELETE CASCADE);
CREATE INDEX idx_skill_grants_token ON skill_grants (token_id);
CREATE TABLE note_embeddings (note_id INTEGER NOT NULL PRIMARY KEY, token_est INTEGER NOT NULL, embedded_text_hash BLOB NOT NULL, embedded_at DATETIME NOT NULL, CONSTRAINT fk_note_embeddings_note FOREIGN KEY (note_id) REFERENCES notes (id) ON DELETE CASCADE);
CREATE VIRTUAL TABLE note_embedding_vectors USING vec0(embedding float[1536] distance_metric=cosine);
CREATE TRIGGER note_embeddings_drop_vector AFTER DELETE ON note_embeddings BEGIN DELETE FROM note_embedding_vectors WHERE rowid = OLD.note_id; END;
CREATE TABLE note_embedding_chunks (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, note_id INTEGER NOT NULL, chunk_index INTEGER NOT NULL, heading VARCHAR(500) DEFAULT NULL, token_est INTEGER NOT NULL, chunk_text_hash BLOB NOT NULL, embedded_at DATETIME NOT NULL, CONSTRAINT fk_note_embedding_chunks_note FOREIGN KEY (note_id) REFERENCES notes (id) ON DELETE CASCADE);
CREATE UNIQUE INDEX uniq_note_embedding_chunks_note_index ON note_embedding_chunks (note_id, chunk_index);
CREATE VIRTUAL TABLE note_embedding_chunk_vectors USING vec0(embedding float[1536] distance_metric=cosine);
CREATE TRIGGER note_embedding_chunks_drop_vector AFTER DELETE ON note_embedding_chunks BEGIN DELETE FROM note_embedding_chunk_vectors WHERE rowid = OLD.id; END;
CREATE VIRTUAL TABLE notes_fts USING fts5(title, body_md, content='notes', content_rowid='id', tokenize='porter unicode61 remove_diacritics 2');
CREATE TRIGGER notes_fts_insert AFTER INSERT ON notes BEGIN INSERT INTO notes_fts (rowid, title, body_md) VALUES (NEW.id, NEW.title, NEW.body_md); END;
CREATE TRIGGER notes_fts_delete AFTER DELETE ON notes BEGIN INSERT INTO notes_fts (notes_fts, rowid, title, body_md) VALUES ('delete', OLD.id, OLD.title, OLD.body_md); END;
CREATE TRIGGER notes_fts_update AFTER UPDATE OF title, body_md ON notes BEGIN INSERT INTO notes_fts (notes_fts, rowid, title, body_md) VALUES ('delete', OLD.id, OLD.title, OLD.body_md); INSERT INTO notes_fts (rowid, title, body_md) VALUES (NEW.id, NEW.title, NEW.body_md); END;
CREATE TRIGGER notes_body_limit_insert BEFORE INSERT ON notes WHEN memex_body_over_limit(length(CAST(NEW.body_md AS BLOB))) AND NOT EXISTS (SELECT 1 FROM deleted_notes d WHERE d.id = NEW.id AND d.purged_at IS NULL AND d.body_md = NEW.body_md) BEGIN SELECT RAISE(ABORT, 'MEMEX_BODY_LIMIT'); END;
CREATE TRIGGER notes_body_limit_update BEFORE UPDATE OF body_md, id ON notes WHEN (NEW.id IS NOT OLD.id OR length(CAST(NEW.body_md AS BLOB)) > length(CAST(OLD.body_md AS BLOB))) AND memex_body_over_limit(length(CAST(NEW.body_md AS BLOB))) BEGIN SELECT RAISE(ABORT, 'MEMEX_BODY_LIMIT'); END;
CREATE TRIGGER notes_restore_consumes_tombstone AFTER INSERT ON notes BEGIN DELETE FROM deleted_notes WHERE id = NEW.id AND purged_at IS NULL; END;
CREATE TRIGGER deleted_notes_body_limit_insert BEFORE INSERT ON deleted_notes WHEN memex_body_over_limit(length(CAST(coalesce(NEW.body_md, '') AS BLOB))) AND NOT EXISTS (SELECT 1 FROM notes n WHERE n.id = NEW.id AND n.body_md = NEW.body_md) BEGIN SELECT RAISE(ABORT, 'MEMEX_BODY_LIMIT'); END;
CREATE TRIGGER deleted_notes_body_limit_update BEFORE UPDATE OF body_md, id ON deleted_notes WHEN (NEW.id IS NOT OLD.id OR length(CAST(coalesce(NEW.body_md, '') AS BLOB)) > length(CAST(coalesce(OLD.body_md, '') AS BLOB))) AND memex_body_over_limit(length(CAST(coalesce(NEW.body_md, '') AS BLOB))) BEGIN SELECT RAISE(ABORT, 'MEMEX_BODY_LIMIT'); END;
